#include <onnxruntime_cxx_api.h>
#include <iostream>
#include <vector>


/*

What This Does:

Loads the trained ML model in C++.
Feeds real-time price data into the model.
Predicts the next price movement using AI.

 */

int main() {
    Ort::Env env(ORT_LOGGING_LEVEL_WARNING, "PricePredictor");
    Ort::Session session(env, "price_model.onnx", Ort::SessionOptions{});

    std::vector<float> input = {150.0, 155.0, 148.0, 1000000};  // Example market data
    std::vector<int64_t> inputShape = {1, 4};  // 1 row, 4 features

    // Prepare inputs
    Ort::MemoryInfo memoryInfo = Ort::MemoryInfo::CreateCpu(OrtArenaAllocator, OrtMemTypeDefault);
    Ort::Value inputTensor = Ort::Value::CreateTensor<float>(memoryInfo, input.data(), input.size(), inputShape.data(), inputShape.size());

    // Run inference
    auto outputTensors = session.Run(Ort::RunOptions{nullptr}, &inputTensor, 1);

    // Display prediction
    float* prediction = outputTensors.front().GetTensorMutableData<float>();
    std::cout << "Predicted Next Price: " << prediction[0] << std::endl;

    return 0;
}

