-- =============================================================================
-- @file    moving_average_trader.vhd
-- @brief   Simple moving average (SMA) trading signal generator
-- @detail  Maintains a shift register of the last WINDOW price samples and
--          computes their mean.  Buy/sell signals are emitted when the current
--          price crosses the moving average by more than the spread threshold.
--
--          Signal logic (simplified — no position tracking):
--            price_in < (moving_avg - spread)  ->  BUY  signal
--            price_in > (moving_avg + spread)  ->  SELL signal
--
--          Prices are assumed to be integer-scaled ×100 (e.g. $100.50 -> 10050).
--          Spread is a constant generic in the same ×100 units.
--
--          Pipeline: 2 clock cycle latency from valid_in to valid_out.
--            Cycle 1: shift register update + running sum update
--            Cycle 2: average division + threshold comparison
--
-- @author  HFT Practice Project
-- @version 1.0
--
-- @generics
--   WINDOW     : number of price samples in the moving average (default 20)
--   PRICE_BITS : width of each price sample in bits (default 32)
--   SPREAD     : constant spread threshold in ×100 price units (default 100 = $1.00)
-- =============================================================================

library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

-- =============================================================================
-- Entity
-- =============================================================================
entity moving_average_trader is
    generic (
        WINDOW     : positive := 20;        -- SMA window length
        PRICE_BITS : positive := 32;        -- Bits per price sample
        SPREAD     : integer  := 100        -- Constant spread (×100 price units)
    );
    port (
        -- Clock / reset
        clk      : in  std_logic;           -- Rising-edge clock
        rst_n    : in  std_logic;           -- Active-low synchronous reset

        -- Input price (integer, scaled ×100)
        price_in : in  signed(PRICE_BITS-1 downto 0);

        -- Input handshake
        valid_in : in  std_logic;

        -- Output trading signals (one-cycle pulses, coincident with valid_out)
        buy_signal  : out std_logic;        -- Assert to place a BUY order
        sell_signal : out std_logic;        -- Assert to place a SELL order

        -- Output handshake
        valid_out : out std_logic
    );
end entity moving_average_trader;

-- =============================================================================
-- Architecture
-- =============================================================================
architecture rtl of moving_average_trader is

    -- -------------------------------------------------------------------------
    -- Type definitions
    -- -------------------------------------------------------------------------
    -- Shift-register array: stores last WINDOW price samples
    type price_array_t is array (0 to WINDOW-1) of signed(PRICE_BITS-1 downto 0);

    -- Running sum needs enough bits: PRICE_BITS + log2(WINDOW)
    -- For PRICE_BITS=32 and WINDOW=20 add 5 bits -> 37 bits; use 48 for margin
    constant SUM_BITS : positive := PRICE_BITS + 8;

    -- -------------------------------------------------------------------------
    -- Shift register and running sum
    -- -------------------------------------------------------------------------
    signal price_reg    : price_array_t             := (others => (others => '0'));
    signal running_sum  : signed(SUM_BITS-1 downto 0) := (others => '0');
    signal sample_count : integer range 0 to WINDOW  := 0;  -- warm-up counter
    signal warmed_up    : std_logic                  := '0';

    -- Stage-1 outputs (registered after shift-register update)
    signal sum_s1       : signed(SUM_BITS-1 downto 0) := (others => '0');
    signal price_s1     : signed(PRICE_BITS-1 downto 0) := (others => '0');
    signal valid_s1     : std_logic                   := '0';
    signal warmed_s1    : std_logic                   := '0';

    -- Stage-2 outputs
    signal buy_r        : std_logic := '0';
    signal sell_r       : std_logic := '0';
    signal valid_s2     : std_logic := '0';

    -- Moving average (registered)
    signal moving_avg   : signed(PRICE_BITS-1 downto 0) := (others => '0');

    -- Spread as a signed constant for comparison arithmetic
    constant SPREAD_S : signed(PRICE_BITS-1 downto 0) :=
        to_signed(SPREAD, PRICE_BITS);

begin

    -- =========================================================================
    -- Stage 1: Update shift register and running sum
    --
    -- The shift register implements a FIFO of length WINDOW.
    -- The oldest sample (price_reg(WINDOW-1)) is subtracted from the running
    -- sum; the newest sample (price_in) is added.  This gives O(1) sum update
    -- regardless of window size, avoiding a long adder chain.
    -- =========================================================================
    stage1_shift : process(clk)
    begin
        if rising_edge(clk) then
            if rst_n = '0' then
                price_reg    <= (others => (others => '0'));
                running_sum  <= (others => '0');
                sample_count <= 0;
                warmed_up    <= '0';
                sum_s1       <= (others => '0');
                price_s1     <= (others => '0');
                valid_s1     <= '0';
                warmed_s1    <= '0';
            else
                valid_s1  <= valid_in;
                price_s1  <= price_in;

                if valid_in = '1' then
                    -- Shift register: oldest falls off the top
                    for i in WINDOW-1 downto 1 loop
                        price_reg(i) <= price_reg(i-1);
                    end loop;
                    price_reg(0) <= price_in;

                    -- Incremental sum update
                    if warmed_up = '1' then
                        -- Full window: subtract outgoing, add incoming
                        running_sum <= running_sum
                                       + resize(price_in,        SUM_BITS)
                                       - resize(price_reg(WINDOW-1), SUM_BITS);
                    else
                        -- Warm-up: just accumulate until we have WINDOW samples
                        running_sum <= running_sum + resize(price_in, SUM_BITS);
                        if sample_count = WINDOW - 1 then
                            warmed_up    <= '1';
                            sample_count <= WINDOW;
                        else
                            sample_count <= sample_count + 1;
                        end if;
                    end if;
                end if;

                -- Pass warm-up flag and sum to stage 2
                sum_s1    <= running_sum;
                warmed_s1 <= warmed_up;
            end if;
        end if;
    end process stage1_shift;

    -- =========================================================================
    -- Stage 2: Compute moving average and emit signals
    --
    -- Division by WINDOW is implemented as multiplication by the reciprocal
    -- when WINDOW is a power of two (right-shift).  For arbitrary WINDOW sizes
    -- a simple repeated-subtraction or DSP divide can be used.  Here we use
    -- a direct division expression, which synthesis will implement using DSP
    -- slices or LUT-based dividers.
    --
    -- NOTE: for production use at 250 MHz, replace the division with a
    -- pipelined integer divider IP core to meet timing.
    -- =========================================================================
    stage2_compare : process(clk)
        variable avg : signed(PRICE_BITS-1 downto 0);
    begin
        if rising_edge(clk) then
            if rst_n = '0' then
                buy_r    <= '0';
                sell_r   <= '0';
                valid_s2 <= '0';
                moving_avg <= (others => '0');
            else
                valid_s2 <= valid_s1 and warmed_s1;
                buy_r    <= '0';
                sell_r   <= '0';

                if valid_s1 = '1' and warmed_s1 = '1' then
                    -- Divide running sum by window length; truncate to PRICE_BITS
                    avg := resize(sum_s1 / to_signed(WINDOW, SUM_BITS), PRICE_BITS);
                    moving_avg <= avg;

                    -- Buy when price is below (average - spread): upward mean reversion
                    if price_s1 < avg - SPREAD_S then
                        buy_r <= '1';
                    -- Sell when price is above (average + spread): downward mean reversion
                    elsif price_s1 > avg + SPREAD_S then
                        sell_r <= '1';
                    end if;
                end if;
            end if;
        end if;
    end process stage2_compare;

    -- Drive outputs
    buy_signal  <= buy_r;
    sell_signal <= sell_r;
    valid_out   <= valid_s2;

end architecture rtl;

/**
 * @file sample_with_gradient_boosting.cpp
 * @brief Moving-average mean-reversion trading simulation using gradient-boosting
 *        inspired signal generation.
 *
 * @details Simulates a simple mean-reversion strategy over @c NUM_TRADES synthetic
 *          price ticks.  The "gradient boosting" framing refers to the intended
 *          production extension: replace the moving-average threshold signal with
 *          predictions from a gradient-boosted tree model loaded via ONNX Runtime
 *          (see @c main.cpp in this directory for the ONNX inference example).
 *
 *          Strategy logic:
 *          - Maintain a rolling moving average of the last @c MOVING_AVG_WINDOW prices.
 *          - Buy one share when price falls more than @c SPREAD below the average
 *            (mean-reversion long entry).
 *          - Sell one share when price rises more than @c SPREAD above the average
 *            and the current position is positive (exit / mean-reversion short).
 *          - Accumulate a running cash balance and position count across all ticks.
 *
 * @author  Brandon Lee
 * @version 0.2.0
 * @date    2026-05-10
 */

#include <iostream>
#include <vector>
#include <cstdlib>
#include <ctime>

// ---------------------------------------------------------------------------
// Strategy parameters
// ---------------------------------------------------------------------------

/// @brief Total number of simulated price ticks to process.
const int NUM_TRADES = 1000;

/// @brief Lookback window (in ticks) for the rolling moving average.
const int MOVING_AVG_WINDOW = 20;

/**
 * @brief Dead-band threshold around the moving average.
 *
 * @details A buy signal is generated only when the current price is more than
 *          @c SPREAD below the moving average, and a sell signal only when the
 *          price is more than @c SPREAD above it.  This prevents excessive trading
 *          near the average when price oscillates within noise.
 */
const double SPREAD = 0.05;

// ---------------------------------------------------------------------------
// Signal generation
// ---------------------------------------------------------------------------

/**
 * @brief Computes the simple moving average of the most recent @p window prices.
 *
 * @details If fewer than @p window prices are available (warm-up period), returns
 *          the last price instead of a partial average so that the strategy does
 *          not generate false signals before the window is full.
 *
 *          Time complexity: O(@p window) — a production implementation should
 *          maintain an incremental running sum for O(1) updates.
 *
 * @param prices  Historical price vector; newest price is at the back.
 * @param window  Number of most-recent prices to include in the average.
 * @return The simple moving average, or the last price if @p prices is shorter
 *         than @p window.
 */
double calculateMovingAverage(const std::vector<double>& prices, int window) {
    if (static_cast<int>(prices.size()) < window) {
        // Warm-up guard: return last price so no signal is generated early.
        return prices.back();
    }

    double sum = 0.0;
    // Sum only the most recent 'window' prices.
    for (int i = static_cast<int>(prices.size()) - window;
         i < static_cast<int>(prices.size()); ++i) {
        sum += prices[i];
    }
    return sum / static_cast<double>(window);
}

// ---------------------------------------------------------------------------
// Entry point
// ---------------------------------------------------------------------------

/**
 * @brief Runs the moving-average mean-reversion simulation.
 *
 * @details Generates @c NUM_TRADES synthetic price ticks with uniform random
 *          increments in [−1.0, +1.0], then applies the mean-reversion strategy.
 *          Prints a trade log to stdout and a final P&L summary.
 *
 *          To extend with a real gradient-boosting model:
 *            1. Export the trained GBM to ONNX (see @c gradient_boosting/model_to_onnx.py).
 *            2. Load the ONNX model with ONNX Runtime (see @c gradient_boosting/main.cpp).
 *            3. Replace the @c movingAvg threshold comparison with the model's
 *               predicted return — buy when @c prediction > threshold, sell otherwise.
 *
 * @return @c 0 on success.
 */
int main() {
    std::srand(static_cast<unsigned>(std::time(nullptr)));  // Seed PRNG.

    std::vector<double> prices;   ///< Rolling price history.
    double cash     = 10000.0;    ///< Starting cash balance (USD).
    int    position = 0;          ///< Current share count (long only in this demo).
    double price    = 100.0;      ///< Starting price.

    for (int i = 0; i < NUM_TRADES; ++i) {
        // Simulate a random walk: price moves by a uniform value in (−1, +1).
        price += (std::rand() % 200 - 100) / 100.0;
        prices.push_back(price);

        // Compute the rolling moving average signal.
        double movingAvg = calculateMovingAverage(prices, MOVING_AVG_WINDOW);

        if (price < movingAvg - SPREAD) {
            // Price has dipped below the average by more than the spread —
            // mean-reversion expects a recovery: BUY.
            cash     -= price;
            position += 1;
            std::cout << "BUY at "  << price
                      << " | Cash: "     << cash
                      << " | Position: " << position << "\n";

        } else if (price > movingAvg + SPREAD && position > 0) {
            // Price has risen above the average by more than the spread and
            // we hold a long position — exit the trade: SELL.
            cash     += price;
            position -= 1;
            std::cout << "SELL at " << price
                      << " | Cash: "     << cash
                      << " | Position: " << position << "\n";
        }
        // Otherwise price is within the dead-band — hold current position.
    }

    // Print final portfolio snapshot.
    std::cout << "\nFinal Cash: "     << cash
              << " | Final Position: " << position
              << " | Last Price: "     << price << "\n";

    return 0;
}

