#include <iostream>
#include <curl/curl.h>
#include <string>

/*

What This Does:

Uses cURL to send a GET request to Alpha Vantage.
Fetches real-time stock prices for AAPL (Apple Inc.).
Prints the API response (JSON format).
🔹 Next Steps: Parse the JSON response and extract prices for your trading algorithm
*/

std::string dataBuffer;

// Callback function to write API response to dataBuffer
size_t WriteCallback(void* contents, size_t size, size_t nmemb, void* userp) {
    size_t totalSize = size * nmemb;
    dataBuffer.append((char*)contents, totalSize);
    return totalSize;
}

void fetchMarketData() {
    std::string apiKey = "YOUR_API_KEY";  // Get a free API key from Alpha Vantage
    std::string url = "https://www.alphavantage.co/query?function=TIME_SERIES_INTRADAY&symbol=AAPL&interval=1min&apikey=" + apiKey;

    CURL* curl;
    CURLcode res;
    curl = curl_easy_init();

    if (curl) {
        curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, WriteCallback);
        curl_easy_setopt(curl, CURLOPT_WRITEDATA, &dataBuffer);
        res = curl_easy_perform(curl);
        curl_easy_cleanup(curl);

        if (res == CURLE_OK) {
            std::cout << "Market Data: " << dataBuffer << std::endl;
        } else {
            std::cerr << "Failed to fetch data" << std::endl;
        }
    }
}

int main() {
    fetchMarketData();
    return 0;
}

