1	-- =============================================================================
2	-- @file    moving_average_trader.vhd
3	-- @brief   Simple moving average (SMA) trading signal generator
4	-- @detail  Maintains a shift register of the last WINDOW price samples and
5	--          computes their mean.  Buy/sell signals are emitted when the current
6	--          price crosses the moving average by more than the spread threshold.
7	--
8	--          Signal logic (simplified — no position tracking):
9	--            price_in < (moving_avg - spread)  ->  BUY  signal
10	--            price_in > (moving_avg + spread)  ->  SELL signal
11	--
12	--          Prices are assumed to be integer-scaled ×100 (e.g. $100.50 -> 10050).
13	--          Spread is a constant generic in the same ×100 units.
14	--
15	--          Pipeline: 2 clock cycle latency from valid_in to valid_out.
16	--            Cycle 1: shift register update + running sum update
17	--            Cycle 2: average division + threshold comparison
18	--
19	-- @author  HFT Practice Project
20	-- @version 1.0
21	--
22	-- @generics
23	--   WINDOW     : number of price samples in the moving average (default 20)
24	--   PRICE_BITS : width of each price sample in bits (default 32)
25	--   SPREAD     : constant spread threshold in ×100 price units (default 100 = $1.00)
26	-- =============================================================================
27	
28	library ieee;
29	use ieee.std_logic_1164.all;
30	use ieee.numeric_std.all;
31	
32	-- =============================================================================
33	-- Entity
34	-- =============================================================================
35	entity moving_average_trader is
36	    generic (
37	        WINDOW     : positive := 20;        -- SMA window length
38	        PRICE_BITS : positive := 32;        -- Bits per price sample
39	        SPREAD     : integer  := 100        -- Constant spread (×100 price units)
40	    );
41	    port (
42	        -- Clock / reset
43	        clk      : in  std_logic;           -- Rising-edge clock
44	        rst_n    : in  std_logic;           -- Active-low synchronous reset
45	
46	        -- Input price (integer, scaled ×100)
47	        price_in : in  signed(PRICE_BITS-1 downto 0);
48	
49	        -- Input handshake
50	        valid_in : in  std_logic;
51	
52	        -- Output trading signals (one-cycle pulses, coincident with valid_out)
53	        buy_signal  : out std_logic;        -- Assert to place a BUY order
54	        sell_signal : out std_logic;        -- Assert to place a SELL order
55	
56	        -- Output handshake
57	        valid_out : out std_logic
58	    );
59	end entity moving_average_trader;
60	
61	-- =============================================================================
62	-- Architecture
63	-- =============================================================================
64	architecture rtl of moving_average_trader is
65	
66	    -- -------------------------------------------------------------------------
67	    -- Type definitions
68	    -- -------------------------------------------------------------------------
69	    -- Shift-register array: stores last WINDOW price samples
70	    type price_array_t is array (0 to WINDOW-1) of signed(PRICE_BITS-1 downto 0);
71	
72	    -- Running sum needs enough bits: PRICE_BITS + log2(WINDOW)
73	    -- For PRICE_BITS=32 and WINDOW=20 add 5 bits -> 37 bits; use 48 for margin
74	    constant SUM_BITS : positive := PRICE_BITS + 8;
75	
76	    -- -------------------------------------------------------------------------
77	    -- Shift register and running sum
78	    -- -------------------------------------------------------------------------
79	    signal price_reg    : price_array_t             := (others => (others => '0'));
80	    signal running_sum  : signed(SUM_BITS-1 downto 0) := (others => '0');
81	    signal sample_count : integer range 0 to WINDOW  := 0;  -- warm-up counter
82	    signal warmed_up    : std_logic                  := '0';
83	
84	    -- Stage-1 outputs (registered after shift-register update)
85	    signal sum_s1       : signed(SUM_BITS-1 downto 0) := (others => '0');
86	    signal price_s1     : signed(PRICE_BITS-1 downto 0) := (others => '0');
87	    signal valid_s1     : std_logic                   := '0';
88	    signal warmed_s1    : std_logic                   := '0';
89	
90	    -- Stage-2 outputs
91	    signal buy_r        : std_logic := '0';
92	    signal sell_r       : std_logic := '0';
93	    signal valid_s2     : std_logic := '0';
94	
95	    -- Moving average (registered)
96	    signal moving_avg   : signed(PRICE_BITS-1 downto 0) := (others => '0');
97	
98	    -- Spread as a signed constant for comparison arithmetic
99	    constant SPREAD_S : signed(PRICE_BITS-1 downto 0) :=
100	        to_signed(SPREAD, PRICE_BITS);
101	
102	begin
103	
104	    -- =========================================================================
105	    -- Stage 1: Update shift register and running sum
106	    --
107	    -- The shift register implements a FIFO of length WINDOW.
108	    -- The oldest sample (price_reg(WINDOW-1)) is subtracted from the running
109	    -- sum; the newest sample (price_in) is added.  This gives O(1) sum update
110	    -- regardless of window size, avoiding a long adder chain.
111	    -- =========================================================================
112	    stage1_shift : process(clk)
113	    begin
114	        if rising_edge(clk) then
115	            if rst_n = '0' then
116	                price_reg    <= (others => (others => '0'));
117	                running_sum  <= (others => '0');
118	                sample_count <= 0;
119	                warmed_up    <= '0';
120	                sum_s1       <= (others => '0');
121	                price_s1     <= (others => '0');
122	                valid_s1     <= '0';
123	                warmed_s1    <= '0';
124	            else
125	                valid_s1  <= valid_in;
126	                price_s1  <= price_in;
127	
128	                if valid_in = '1' then
129	                    -- Shift register: oldest falls off the top
130	                    for i in WINDOW-1 downto 1 loop
131	                        price_reg(i) <= price_reg(i-1);
132	                    end loop;
133	                    price_reg(0) <= price_in;
134	
135	                    -- Incremental sum update
136	                    if warmed_up = '1' then
137	                        -- Full window: subtract outgoing, add incoming
138	                        running_sum <= running_sum
139	                                       + resize(price_in,        SUM_BITS)
140	                                       - resize(price_reg(WINDOW-1), SUM_BITS);
141	                    else
142	                        -- Warm-up: just accumulate until we have WINDOW samples
143	                        running_sum <= running_sum + resize(price_in, SUM_BITS);
144	                        if sample_count = WINDOW - 1 then
145	                            warmed_up    <= '1';
146	                            sample_count <= WINDOW;
